{"implementation":"import json
def solve(case):
    nodes = case['payload']['nodes']
    core_dist = case['payload']['core_distance']
    dist_list = case['payload']['distances']
    dist_dict = {}
    for u, v, d in dist_list:
        key = (min(u, v), max(u, v))
        dist_dict[key] = d
    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i + 1, n):
            u = nodes[i]
            v = nodes[j]
            d = dist_dict[(u, v)]
            mrd = max(core_dist[u], core_dist[v], d)
            edges.append((mrd, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        parent[ry] = rx
        return True
    mst_edges = []
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append((w, u, v))
            if len(mst_edges) == n - 1:
                break
    mst_edges_sorted = sorted(mst_edges, key=lambda x: (x[0], x[1], x[2]))
    mst_result = [[u, v, w] for w, u, v in mst_edges_sorted]
    all_edges = [[u, v, w] for w, u, v in edges]
    return {
        'mutual_reachability_edges': all_edges,
        'mst_edges': mst_result
    }"}
